//! Determinism probe for clonk-org/clonk-rs#1864: per-frame digest of the
//! full SimulationSnapshot (Debug) + sync check, plus advance timing.
use std::collections::hash_map::DefaultHasher;
use std::env;
use std::hash::{Hash, Hasher};
use std::io::Write;
use std::path::PathBuf;
use std::time::{Duration, Instant};

use clonk_engine::scenario::{load_system_scripts, LegacyDefinitionResolver};
use clonk_engine::{Engine, JoinPlayerConfig, JoinPlayerOutcome, Scenario, ScenarioError};
use clonk_resources::{Group, MaterialLibrary};

mod alloc_count {
    use std::alloc::{GlobalAlloc, Layout, System};
    use std::cell::Cell;
    use std::collections::HashMap;
    use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
    use std::sync::Mutex;
    pub static ARMED: AtomicBool = AtomicBool::new(false);
    pub static COUNT: AtomicU64 = AtomicU64::new(0);
    pub static BYTES: AtomicU64 = AtomicU64::new(0);
    pub static SAMPLE_EVERY: AtomicU64 = AtomicU64::new(0);
    pub static SITES: Mutex<Option<HashMap<String, u64>>> = Mutex::new(None);
    thread_local! { static IN_HOOK: Cell<bool> = const { Cell::new(false) }; }
    pub struct Counting;
    unsafe impl GlobalAlloc for Counting {
        unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
            if ARMED.load(Ordering::Relaxed) && !IN_HOOK.with(|h| h.get()) {
                let n = COUNT.fetch_add(1, Ordering::Relaxed);
                BYTES.fetch_add(layout.size() as u64, Ordering::Relaxed);
                let every = SAMPLE_EVERY.load(Ordering::Relaxed);
                if every != 0 && n % every == 0 {
                    IN_HOOK.with(|h| h.set(true));
                    let bt = std::backtrace::Backtrace::force_capture().to_string();
                    let mut frames: Vec<String> = Vec::new();
                    const DENY: &[&str] = &["alloc","__rust_alloc","alloc_impl_runtime","alloc_impl","allocate","do_alloc","new_uninitialized","fallible_with_capacity","prepare_resize","resize_inner","reserve_rehash_inner","reserve_rehash","reserve","reserve_for_push","with_capacity","with_capacity_in","try_allocate_in","to_vec","to_vec_in","clone","extend","extend_trusted","extend_desugared","spec_extend","from_iter","collect","new","push","push_mut","grow_one","grow_amortized","finish_grow","insert","entry","or_insert_with","or_default","map","and_then","then","unwrap_or_else","or_else","map_or","call_once","call_mut","{closure#0}","{closure#1}","{closure#2}","{closure#3}","fold","for_each","try_fold","maybe_grow","with","try_with","new_uninit","default","into","from","clone_from","clone_from_impl","clone_from_spec","to_owned","to_string","format","format_inner","realloc","into_boxed_slice","box_new","new_in","try_new_uninit_in","cloned","copied","get_or_insert_with","retain","spec_from_iter","spec_from_iter_nested","from_iter_in_place","next","try_process","is_some_and","is_none_or","filter","filter_map"];
                    for line in bt.lines() {
                        let t = line.trim();
                        let Some((num, rest)) = t.split_once(": ") else { continue };
                        if !num.chars().all(|c| c.is_ascii_digit()) { continue; }
                        if rest.starts_with('<') { continue; }
                        let mut name = String::new(); let mut depth = 0;
                        for ch in rest.chars() { match ch { '<' => depth += 1, '>' => depth -= 1, _ if depth == 0 => name.push(ch), _ => {} } }
                        let base = name.rsplit("::").next().unwrap_or(&name).to_string();
                        if DENY.contains(&base.as_str()) || name.starts_with("std::") || name.starts_with("core::") || name.starts_with("alloc::") { continue; }
                        frames.push(name);
                        if frames.len() >= 3 { break; }
                    }
                    if std::env::var("BT_DUMP").is_ok() && n % (every * 500) == 0 { eprintln!("{bt}"); }
                    let mut key = frames.join(" < ");
                    if let Ok(focus) = std::env::var("ALLOC_FOCUS") {
                        if !bt.contains(&focus) { IN_HOOK.with(|h| h.set(false)); return unsafe { System.alloc(layout) }; }
                        // first raw frame mentioning a clonk type in generics
                        key = bt.lines().map(str::trim).filter_map(|t| t.split_once(": ").map(|x| x.1))
                            .filter(|r| !["alloc","__rust_alloc","alloc::alloc::alloc","allocate","alloc_impl","alloc_impl_runtime","do_alloc","new_uninitialized","fallible_with_capacity","try_allocate_in"].iter().any(|d| r == d || r.starts_with(&format!("{d}<")) || r.starts_with("<alloc::alloc::Global") || r.starts_with("<alloc::raw_vec") || r.starts_with("alloc::alloc")))
                            .take(4).map(|r| r.chars().take(90).collect::<String>()).collect::<Vec<_>>().join(" | ");
                    }
                    if let Ok(mut g) = SITES.lock() { *g.get_or_insert_with(HashMap::new).entry(key).or_default() += 1; }
                    IN_HOOK.with(|h| h.set(false));
                }
            }
            unsafe { System.alloc(layout) }
        }
        unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) { unsafe { System.dealloc(ptr, layout) } }
        unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new: usize) -> *mut u8 {
            if ARMED.load(Ordering::Relaxed) && !IN_HOOK.with(|h| h.get()) { COUNT.fetch_add(1, Ordering::Relaxed); BYTES.fetch_add(new as u64, Ordering::Relaxed); }
            unsafe { System.realloc(ptr, layout, new) }
        }
    }
}
#[global_allocator]
static GLOBAL: alloc_count::Counting = alloc_count::Counting;
use std::sync::atomic::Ordering;

struct ContentResolver { roots: Vec<PathBuf> }
impl LegacyDefinitionResolver for ContentResolver {
    fn resolve_definition_groups(&self, _s: &Group, identifier: &str) -> Result<Vec<Group>, ScenarioError> {
        let relative = identifier.replace('\\', "/");
        self.roots.iter().map(|r| r.join(&relative)).find(|c| c.exists()).map(Group::open)
            .transpose().map_err(ScenarioError::Resources)?.map(|g| vec![g])
            .ok_or_else(|| ScenarioError::LegacyDefinitionNotFound { path: relative })
    }
}

fn join(engine: &mut Engine, name: &str, team: i32) -> Option<i32> {
    let outcome = engine.join_player(JoinPlayerConfig {
        name: name.to_owned(), player_info_id: 0, score: 0, rounds: 0, rounds_won: 0, rounds_lost: 0,
        total_playing_time: 0, team: None, color_dw: 0xff_00_00, pref_color: 0, pref_position: 0,
        crew: Vec::new(), control_style: false, auto_context_menu: false, startup_player_count: 1,
    }).ok()?;
    match outcome {
        JoinPlayerOutcome::Initialized(p) => Some(p.number),
        JoinPlayerOutcome::AwaitingTeamSelection { number } =>
            engine.initialize_scenario_player(number, team).ok()?.map(|p| p.number),
    }
}

fn canonical(value: serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Object(map) => {
            let mut entries: Vec<_> = map.into_iter().collect();
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            serde_json::Value::Object(entries.into_iter().map(|(k, v)| (k, canonical(v))).collect())
        }
        serde_json::Value::Array(items) => serde_json::Value::Array(items.into_iter().map(canonical).collect()),
        other => other,
    }
}

fn main() {
    let repo = PathBuf::from("/home/alex/.t3/worktrees/clonk-rs/t3-ab85cb94");
    let content = PathBuf::from(env::var("LC_CONTENT_ROOT").unwrap_or("/home/alex/dev/clonk-rs/content".into()));
    let install = content.parent().unwrap().to_path_buf();
    let mut args = env::args().skip(1);
    let rel = args.next().expect("scenario");
    let frames: usize = args.next().and_then(|v| v.parse().ok()).unwrap_or(1000);
    let seed: u64 = args.next().and_then(|v| v.parse().ok()).unwrap_or(0);
    let out = args.next();
    let every: usize = env::var("DIGEST_EVERY").ok().and_then(|v| v.parse().ok()).unwrap_or(1);
    let path = [repo.join(&rel), content.join(&rel)].into_iter().find(|p| p.exists()).expect("scenario exists");
    let scenario = Scenario::load_from_path_with_seed(&path, &ContentResolver { roots: vec![repo.clone(), content.clone()] }, seed).expect("load");
    let materials = MaterialLibrary::from_group(&Group::open(content.join("Material.c4g")).unwrap()).unwrap();
    let system_group = Group::open(install.join("planet/System.c4g")).expect("System");
    let system_scripts = load_system_scripts(&system_group).unwrap();
    let mut engine = Engine::with_seed(seed);
    engine.configure_materials_from_library(&materials);
    engine.install_global_scripts(&system_scripts);
    engine.set_standard_names(system_group.read_file("Names.txt").ok().map(|b| String::from_utf8_lossy(&b).into_owned()));
    scenario.apply(&mut engine).expect("apply");
    let joined: Vec<_> = [join(&mut engine, "Profiler", 1), join(&mut engine, "Profiler 2", 2)].into_iter().flatten().collect();
    let mut file = out.map(|o| std::io::BufWriter::new(std::fs::File::create(o).unwrap()));
    let mut total = DefaultHasher::new();
    if let Ok(v) = env::var("ALLOC_SAMPLE") { alloc_count::SAMPLE_EVERY.store(v.parse().unwrap(), Ordering::Relaxed); }
    let mut times = Vec::with_capacity(frames);
    engine.reset_effect_dispatch_stats();
    for frame in 1..=frames {
        let t = Instant::now();
        alloc_count::ARMED.store(true, Ordering::Relaxed);
        engine.tick_without_snapshot().expect("tick");
        alloc_count::ARMED.store(false, Ordering::Relaxed);
        times.push(t.elapsed());
        if let Ok(prefix) = env::var("STATE_PREFIX") {
            if [1, 100, 300, 600, 1000, 1500].contains(&frame) {
                let state = canonical(serde_json::json!({ "engine": engine.capture_state(), "temperature_scan_x": engine.landscape().map(|landscape| landscape.scan_x()) }));
                std::fs::write(format!("{prefix}-{frame}.json"), serde_json::to_vec(&state).unwrap()).unwrap();
            }
        }
        if frame % every == 0 || frame == frames {
            let snap = engine.snapshot();
            let sync = engine.sync_check(0);
            let mut h = DefaultHasher::new();
            serde_json::to_string(&canonical(serde_json::to_value(&snap).unwrap())).unwrap().hash(&mut h);
            let dbg = format!("{snap:#?}");
            let mut lines: Vec<&str> = dbg.lines().collect();
            lines.sort_unstable();
            lines.hash(&mut h);
            format!("{sync:?}").hash(&mut h);
            let d = h.finish();
            if env::var("DUMP").is_ok() && frame == env::var("DUMP_FRAME").ok().and_then(|v| v.parse().ok()).unwrap_or(1) { std::fs::write(env::var("DUMP").unwrap(), format!("{snap:#?}")).unwrap(); std::fs::write(env::var("DUMP").unwrap() + ".json", serde_json::to_string_pretty(&canonical(serde_json::to_value(&snap).unwrap())).unwrap()).unwrap(); }
            d.hash(&mut total);
            if let Some(f) = file.as_mut() { writeln!(f, "{frame} {d:016x} {sync:?}").unwrap(); }
        }
    }
    if let Ok(path) = env::var("TIMINGS") {
        std::fs::write(path, serde_json::to_vec(&times.iter().map(Duration::as_nanos).collect::<Vec<_>>()).unwrap()).unwrap();
    }
    let sum: Duration = times.iter().sum();
    let mut sorted = times.clone(); sorted.sort();
    let st = engine.effect_dispatch_stats();
    println!("dispatch/tick: world_context_builds={:.1} base={:.1} snapshots={:.1}", st.world_context_builds as f64 / frames as f64, st.context_base_materializations as f64 / frames as f64, st.object_state_snapshots as f64 / frames as f64);
    let allocs = alloc_count::COUNT.load(Ordering::Relaxed) as f64 / frames as f64;
    let bytes = alloc_count::BYTES.load(Ordering::Relaxed) as f64 / frames as f64;
    println!("allocs/tick={allocs:.0} bytes/tick={bytes:.0}");
    if let Some(sites) = alloc_count::SITES.lock().unwrap().take() {
        let total: u64 = sites.values().sum();
        let mut v: Vec<_> = sites.into_iter().collect(); v.sort_by(|a, b| b.1.cmp(&a.1));
        for (k, n) in v.iter().take(60) { println!("{:5.1}% {k}", 100.0 * *n as f64 / total as f64); }
    }
    println!("{rel} joined={joined:?} frames={frames} mean={:?} p50={:?} p95={:?} objects={} digest={:016x}",
        sum / frames as u32, sorted[frames/2], sorted[frames*95/100], engine.snapshot().objects.len(), total.finish());
}

