import pathlib, subprocess, os, concurrent.futures, json, hashlib, statistics, time
root=pathlib.Path('/tmp/clonk-1864')
scenarios=pathlib.Path('/home/alex/.cache/probe-1864/scenarios.txt').read_text().splitlines()
bins={'baseline':str(root/'base-probe/target/release/probe-1864'),'candidate':str(root/'probe/target/release/probe-1864')}
checkpoints=[1,100,300,600,1000,1500]
def validate(s):
 name=pathlib.Path(s).name[:-4]
 for label,binary in bins.items():
  prefix=root/'states'/(name+'-'+label)
  env=os.environ.copy(); env.update(DIGEST_EVERY='100000',STATE_PREFIX=str(prefix))
  p=subprocess.run([binary,s,'1500','0'],env=env,capture_output=True,text=True)
  (root/'states'/(name+'-'+label+'.summary')).write_text(p.stdout+p.stderr)
  if p.returncode: raise RuntimeError(p.stderr)
 pairs=[]
 for frame in checkpoints:
  a=root/'states'/f'{name}-baseline-{frame}.json'; b=root/'states'/f'{name}-candidate-{frame}.json'
  ja=json.loads(a.read_bytes()); jb=json.loads(b.read_bytes()); same=ja==jb
  pairs.append({'frame':frame,'equal':same,'baseline_sha256':hashlib.sha256(a.read_bytes()).hexdigest(),'candidate_sha256':hashlib.sha256(b.read_bytes()).hexdigest()})
  if not same:
   diffs=[]
   def compare(a,b,path=''):
    if isinstance(a,dict) and isinstance(b,dict):
     for key in a.keys()|b.keys(): compare(a.get(key),b.get(key),path+'/'+key)
    elif isinstance(a,list) and isinstance(b,list):
     if len(a)!=len(b): diffs.append([path,'length',len(a),len(b)])
     for i,(x,y) in enumerate(zip(a,b)): compare(x,y,path+'/'+str(i))
    elif a!=b: diffs.append([path,repr(a)[:100],repr(b)[:100]])
   compare(ja,jb); (root/'states'/(name+'-diff.json')).write_text(json.dumps(diffs,indent=2))
 print('state',name,'matches',sum(x['equal'] for x in pairs),'/',len(pairs),flush=True)
 return {'scenario':s,'checkpoints':pairs}
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex: states=list(ex.map(validate,scenarios))
(root/'states-comparison.json').write_text(json.dumps(states,indent=2)+'\n')
if not all(p['equal'] for s in states for p in s['checkpoints']): raise SystemExit('state comparison failed')
print('starting isolated sequential timing pairs',flush=True)
results=[]
for rep in range(3):
 for s in scenarios[:3]:
  name=pathlib.Path(s).name[:-4]
  for label in (['baseline','candidate'] if rep%2==0 else ['candidate','baseline']):
   sample=root/f'timing-{name}-{rep}-{label}.json'
   env=os.environ.copy(); env.update(DIGEST_EVERY='100000',TIMINGS=str(sample))
   p=subprocess.run([bins[label],s,'3200','0'],env=env,capture_output=True,text=True)
   (root/f'timing-{name}-{rep}-{label}.summary').write_text(p.stdout+p.stderr)
   if p.returncode: raise RuntimeError(p.stderr)
   raw=json.loads(sample.read_text()); selected=raw[200:]
   result={'scenario':s,'repetition':rep,'build':label,'frames':3200,'warmup':200,'raw_frame_ns':raw,'mean_ns':statistics.mean(selected),'p50_ns':statistics.median(selected),'p95_ns':sorted(selected)[int(.95*len(selected))],'p99_ns':sorted(selected)[int(.99*len(selected))],'summary':p.stdout}
   results.append(result)
   (root/'timing-pairs.json').write_text(json.dumps(results,indent=2)+'\n')
   print('timing',name,rep,label,round(result['mean_ns']/1e6,3),'ms',flush=True)

